CREATE TABLE privacy_policies (tenant_id uuid PRIMARY KEY REFERENCES tenants(id), analytics_enabled boolean NOT NULL DEFAULT false, analytics_days integer NOT NULL CHECK(analytics_days BETWEEN 1 AND 3650), raw_days integer CHECK(raw_days BETWEEN 1 AND 3650), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE privacy_consents (tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL,analytics boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE privacy_aggregates (tenant_id uuid NOT NULL,publication_id uuid NOT NULL REFERENCES studio_publications(id),day date NOT NULL,metric text NOT NULL CHECK(metric IN ('visit','session','exhibition-dwell','artwork-dwell','room-visit','completed')),resource_id uuid NOT NULL,count bigint NOT NULL CHECK(count BETWEEN 1 AND 1000000000),duration_seconds bigint NOT NULL DEFAULT 0 CHECK(duration_seconds>=0),expires_at timestamptz NOT NULL,PRIMARY KEY(publication_id,day,metric,resource_id));
CREATE TABLE privacy_objects (tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL,owner_user_id uuid NOT NULL,object_key text NOT NULL UNIQUE,sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'),bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 33554432),purpose text NOT NULL CHECK(purpose IN ('raw','temporary','master','web')),expires_at timestamptz,notice_acknowledged_at timestamptz,erased_at timestamptz,PRIMARY KEY(tenant_id,id),CHECK(purpose IN ('raw','temporary') OR expires_at IS NULL));
CREATE TABLE privacy_holds (tenant_id uuid NOT NULL,id uuid NOT NULL,user_id uuid,object_id uuid,kind text NOT NULL CHECK(kind IN ('reference','legal','backup')),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),CHECK((user_id IS NULL)<>(object_id IS NULL)));
CREATE TABLE privacy_deletions (tenant_id uuid NOT NULL,id uuid NOT NULL,user_id uuid NOT NULL,request_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('account','object')),object_id uuid,state text NOT NULL CHECK(state IN ('pending','blocked','removing','erased')),code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,user_id,request_id),CHECK((kind='object')=(object_id IS NOT NULL)));
